<?php require_once __DIR__.'/config/security.php'; require_permission('dashboard.view'); $page_title='Security Monitoring'; $events=$pdo->query("SELECT s.*,u.name FROM security_events s LEFT JOIN users u ON u.id=s.user_id ORDER BY s.created_at DESC LIMIT 150")->fetchAll(); $failed=(int)$pdo->query("SELECT COUNT(*) FROM security_events WHERE event_type='failed_login' AND created_at>=NOW()-INTERVAL 24 HOUR")->fetchColumn(); $critical=(int)$pdo->query("SELECT COUNT(*) FROM security_events WHERE severity='Critical' AND created_at>=NOW()-INTERVAL 24 HOUR")->fetchColumn(); include __DIR__.'/partials/header.php'; ?>
<div class="hero compact"><div><div class="eyebrow">SECURITY OPERATIONS</div><h1>Security monitoring</h1><p>Failed logins, audit events and unusual activity indicators.</p></div></div><div class="stats-grid"><div class="stat-card"><small>FAILED LOGINS · 24H</small><strong><?=$failed?></strong><span>Authentication events</span></div><div class="stat-card"><small>CRITICAL EVENTS · 24H</small><strong><?=$critical?></strong><span>Requires review</span></div><div class="stat-card"><small>ACCOUNT LOCKOUT</small><strong>5</strong><span>Failed attempts</span></div></div>
